For the sake of exposition, assume that regex_iterator contains the following members:

BidirIt begin;
 BidirIt end;
 const regex_type *pregex;
 std::regex_constants::match_flag_type flags;
 std::match_results<BidirIt> match;

1) Returns true if *this and rhs are both end-of-sequence iterators, or if all of the following conditions are true:
 begin == rhs.begin
 end == rhs.end
 pregex == rhs.pregex
 flags == rhs.flags
 match[0] == rhs.match[0]

2) Returns !(*this == rhs).

recommendedExamples.code:
#include <iostream>
#include <regex>
#include <string>

int main() {
    std::string hay{"1.1a2b3cjk34"};
    std::regex needle("[1234]");
    using Ri = std::regex_iterator<std::string::iterator>;
    for (Ri it{hay.begin(), hay.end(), needle}, last{}; it != last; ++it)
        std::cout << it->str();
    std::cout << '\n';
}
